### Description

In useChat, initialMessages is no longer reflected in messages.
Instead of initialMessages, initial values are set in useChat's setMessages.

### Code example

```
export default function Chat({
    id, 
    initialMessages,
}: {
    id?: string | undefined;
    initialMessages?: Message[];
}) {

    const { input, status, handleSubmit, messages, stop, setInput, setMessages } =
    useChat({
        id, // use the provided chatId
        // initialMessages, // initial messages if provided  
        sendExtraMessageFields: true, // send id and createdAt for each message
        generateId: createIdGenerator({ prefix: 'msgc', size: 16 }), // id format for client-side messages  
        onFinish(message, { usage, finishReason }) {
            console.log('Usage', usage);
            console.log('FinishReason', finishReason);
        },
    });

    useEffect(() => {
        if (initialMessages)
            setMessages(initialMessages);
    }, [initialMessages, setMessages]);

```

